SELECT COALESCE(SUM(l.quantity), 0) FROM device_sku_lot l
WHERE l.device_id = #{deviceId} AND l.sku_id = #{skuId}
  AND l.status IN ('ON_SALE', 'NEAR_EXPIRY')


SELECT COUNT(*) FROM device_sku_lot l
WHERE l.status IN ('ON_SALE', 'NEAR_EXPIRY')
  AND l.quantity > 0
  AND l.expiry_date <= #{nearDate}
  AND l.expiry_date > #{today}
